"""Read existing receipts/canonical results only; no physics, integration or timing.

Creates a cost inventory, including NOT_RUN two-factor matrix entries. Component
rows and subtotal rows are explicitly distinguished to prevent double counting.
"""
import csv,json
from pathlib import Path
P=Path(__file__).resolve().parents[1];R=P/'results/probability';OUT=P/'formula_collection/04_PROBABILITY_COST_TWO_FACTOR.csv'
final=json.loads((R/'final_numerical_comparison_v3.json').read_text());one=json.loads((R/'original1d_results_v2.json').read_text())
fields=['row_id','model','probability_rule','physics_factor','cost_role','execution','aggregation_role','task_status','full_complex_RHS_new','full_LU576_new','Schur256_new','reduced_nodes','reduced_complex_RHS256','wall_seconds_recorded','CPU_seconds_recorded','setup_included','online_integral_included','reference_qualification_included','setup_plus_integral_components_wall','full_cold_start_wall','reference_status','denominator_kind','denominator_value_recorded','denominator_rigorous','reference_mean_uncertainty_proxy','reference_event_layer_uncertainty_proxy','omitted_posterior_proxy','source_artifact','source_field','notes']
rows=[]
def add(row):
    name=row.get('model');q=final[name]['reference_qualification'] if name in final else None
    row.setdefault('aggregation_role','COMPONENT');row.setdefault('execution','EXECUTED');row.setdefault('denominator_rigorous','FALSE');row.setdefault('full_cold_start_wall','NOT_RECORDED')
    if q:
        row.setdefault('reference_status',q['status']);row.setdefault('denominator_kind',q['numerical_denominator_formula']);row.setdefault('denominator_value_recorded',q['scaled_evidence_numerical_denominator_proxy']);row.setdefault('reference_mean_uncertainty_proxy',q['mean_absolute_numeric_uncertainty_proxy']);row.setdefault('reference_event_layer_uncertainty_proxy',q['event_or_layer_numeric_uncertainty_proxy']);row.setdefault('omitted_posterior_proxy',q['numerical_omitted_posterior_upper_proxy'])
    rows.append(row)
def method(name,stem,role,status):
    f=R/(stem+'.json');z=json.loads(f.read_text());c=z.get('cost_counts_delta',{})
    add(dict(row_id=stem,model=name,probability_rule=z['method'],physics_factor=z.get('physics','SCHUR_EXACT_ALGEBRA_FLOAT'),cost_role=role,task_status=status,full_complex_RHS_new=c.get('full_complex_RHS',0),full_LU576_new=c.get('full_LU',0),reduced_nodes=c.get('reduced_nodes',0),reduced_complex_RHS256=c.get('reduced_complex_RHS256',0),wall_seconds_recorded=z.get('wall_seconds',''),CPU_seconds_recorded=z.get('CPU_seconds',''),setup_included='FALSE_COMMON_SETUP_SEPARATE',online_integral_included='TRUE',reference_qualification_included='FALSE',source_artifact=str(f.relative_to(P)),source_field='wall_seconds;CPU_seconds;cost_counts_delta',notes='Includes probability/prior/serialization within method timer. Per-method physics/prior wall split was not separately recorded; do not infer it from node counts.'))
probe=json.loads((R/'probe_receipt.json').read_text());tm=probe['timings']
for key,rhs,lu,schur in [('setup_full_host',264,1,0),('Schur256_and_transforms',0,0,1),('setup_diagnostics',0,0,0)]:
    add(dict(row_id=key,model='SHARED_R6_UNIFORM',probability_rule='ALL_RULES_SAME_EVALUATOR',physics_factor='SCHUR_SETUP',cost_role='SETUP',full_complex_RHS_new=rhs,full_LU576_new=lu,Schur256_new=schur,wall_seconds_recorded=tm[key+'_wall'],CPU_seconds_recorded=tm[key+'_CPU'],setup_included='TRUE_ONCE',online_integral_included='FALSE',reference_qualification_included='FALSE',source_artifact='results/probability/probe_receipt.json',source_field='timings.'+key,notes='Nonzero host;264=8source+256ROI basis. Common setup must be counted once per cold fixed operator/ROI, not once per posterior node.'))
add(dict(row_id='probe_direct_validation',model='SHARED_R6_UNIFORM',probability_rule='FROZEN16_AMPLITUDES',physics_factor='DIRECT_VIE',cost_role='VALIDATION',full_complex_RHS_new=128,full_LU576_new=16,wall_seconds_recorded=tm['direct_TM24_wall'],CPU_seconds_recorded=tm['direct_TM24_CPU'],setup_included='FALSE',reference_qualification_included='TRUE',source_artifact='results/probability/probe_receipt.json',source_field='timings.direct_TM24',notes='Validation is not online posterior integration.'))
add(dict(row_id='probe_reduced_validation_and_oldphi_replay',model='SHARED_R6_UNIFORM',probability_rule='16_VALIDATION_PLUS6_STORED_GH21_PHI',physics_factor='SCHUR',cost_role='VALIDATION',full_complex_RHS_new=0,full_LU576_new=0,reduced_nodes=22,reduced_complex_RHS256=176,wall_seconds_recorded=tm['reduced_triangular256_wall'],CPU_seconds_recorded=tm['reduced_triangular256_CPU'],reference_qualification_included='TRUE',source_artifact='results/probability/probe_receipt.json',source_field='counts;timings.reduced_triangular256',notes='Old stored phi is a comparison input; six new reduced evaluations counted.'))
for name,rr in final.items():
    for order in (9,11):
        for physics in ('direct','reduced'):method(name,f'{name}_{physics}_GH{order}','MATCHED_ONLINE_INTEGRAL','NUMERICAL_TASK_PASS')
        comp=rr['two_factor_physical_reuse'][str(order)]
        add(dict(row_id=f'{name}_GH{order}_setup_plus_integral',model=name,probability_rule=f'CORRECT_QUOTIENT_GH{order}',physics_factor='SCHUR',cost_role='COMPONENT_VIEW',aggregation_role='NONADDITIVE_VIEW',setup_plus_integral_components_wall=comp['shared_setup_plus_integral_wall'],setup_included='TRUE_COMMON_SETUP_REUSED',online_integral_included='TRUE',reference_qualification_included='FALSE',source_artifact='results/probability/final_numerical_comparison_v3.json',source_field=f'{name}.two_factor_physical_reuse.{order}',notes=comp['interpretation']))
    for order in (21,31):method(name,f'{name}_reduced_GH{order}','REFERENCE_INTEGRAL','NUMERICAL_REFERENCE_ONLY')
    method(name,f'{name}_reduced_GH31_flat_wrong','WRONG_PRIOR_CONTROL','INCORRECT_MATERIAL_PRIOR')
    for no,ni in [(12,20),(20,32)]:
        method(name,f'{name}_source_GL{no}_{ni}','REFERENCE_CROSS_COORDINATE','NUMERICAL_REFINEMENT_ONLY')
        add(dict(row_id=f'{name}_source_GL{no}_{ni}_direct',model=name,probability_rule=f'ORIGINAL_SOURCE_GL{no}_{ni}',physics_factor='DIRECT_VIE',cost_role='TWO_FACTOR_MISSING_CELL',execution='NOT_RUN',aggregation_role='UNRUN',task_status='NOT_RUN',source_artifact='E4_PROBABILITY_REPORT_ZH.md',source_field='section3',notes='No matched direct original-source integral was executed; do not extrapolate its wall from reduced node count.'))
    for suffix,role in [('_first_run','FIRST_WHOLE_SUPPORT_AUDIT'),('','DETAILED_AUDIT_REPLAY')]:
        f=R/f'{name}_whole_support_audit{suffix}.json';d=json.loads(f.read_text())
        add(dict(row_id=f'{name}_{role}',model=name,probability_rule='WHOLE_SUPPORT_MAJORANT',physics_factor='SCHUR_FLOAT_MAJORANT',cost_role=role,task_status=d['status'],full_complex_RHS_new=0,wall_seconds_recorded=d['wall_seconds'],CPU_seconds_recorded=d['CPU_seconds'],reference_qualification_included='TRUE',source_artifact=str(f.relative_to(P)),source_field='wall_seconds;CPU_seconds;evaluated_cells',notes=f"{d['evaluated_cells']} audited cells; per-case reduced RHS not separately stored in audit JSON. Detailed replay totals are in audit_detail_replay receipt. Floating coefficients/prior denominator not enclosed."))
    env=json.loads((R/f'{name}_task_envelopes.json').read_text())
    for z in env:
        c=z['cost_counts_delta'];add(dict(row_id=f'{name}_task_envelope_L{z["grid_level"]}',model=name,probability_rule='CENTERED_TASK_MOMENTS',physics_factor='SCHUR_FLOAT_MAJORANT',cost_role='PROBABILITY_ENVELOPE',task_status='MEAN_OLD_GATE_UNCLOSED_EVENT_NUMERICAL_ONLY',full_complex_RHS_new=0,full_LU576_new=0,reduced_nodes=c.get('reduced_nodes',0),reduced_complex_RHS256=c.get('reduced_complex_RHS256',0),wall_seconds_recorded=z['wall_seconds'],CPU_seconds_recorded=z['CPU_seconds'],setup_included='FALSE',online_integral_included='TRUE',reference_qualification_included='FALSE',source_artifact=f'results/probability/{name}_task_envelopes.json',source_field=f'grid_level={z["grid_level"]}',notes='Prior moments are numerical GL3/fibreGL96. Entire-cell Schur bound lacks outward coefficient arithmetic; strict intervals NULL.'))
    add(dict(row_id=f'{name}_centered_task_direct',model=name,probability_rule='CENTERED_TASK_MOMENTS',physics_factor='DIRECT_VIE',cost_role='TWO_FACTOR_MISSING_CELL',execution='NOT_RUN',aggregation_role='UNRUN',task_status='NOT_RUN',source_artifact='E4_PROBABILITY_REPORT_ZH.md',source_field='section3/4',notes='Reduced mean tolerance was not closed; no completed direct probability-envelope benchmark.'))
for z in one['references']:
    add(dict(row_id='P1_1d_'+z['coordinates'],model='P1_ORIGINAL_OFFSET_1D',probability_rule=z['coordinates'],physics_factor='SCHUR',cost_role='REFERENCE_INTEGRAL',task_status='NUMERICAL_CONDITIONAL_TASK_PASS',full_complex_RHS_new=0,full_LU576_new=0,reduced_nodes=z['phi_calls'],reduced_complex_RHS256=z['phi_calls']*8,wall_seconds_recorded=z['wall'],CPU_seconds_recorded=z['CPU'],setup_included='FALSE',online_integral_included='TRUE',reference_qualification_included='TRUE',reference_status='NUMERICAL_REFERENCE',denominator_kind='DIRECT_NUMERICAL_QUAD_SCALED_EVIDENCE_NOT_A_LOWER_BOUND',denominator_value_recorded=z['scaled_evidence'],source_artifact='results/probability/original1d_results_v2.json',source_field='references.'+z['coordinates'],notes='Four task/evidence integral calls; exact saturation prior atom masses retained. Event quadrature underflow is flagged; use nonzero envelope upper.'))
for z in one['envelope_trajectory']:
    add(dict(row_id=f'P1_1d_centered_cells{z["cells"]}',model='P1_ORIGINAL_OFFSET_1D',probability_rule='CENTERED_QUINTIC_GAUSSIAN_TASK_MOMENTS',physics_factor='SCHUR_FLOAT_MAJORANT',cost_role='ENVELOPE_CUMULATIVE_STOP',aggregation_role='NONADDITIVE_CUMULATIVE_TRAJECTORY',task_status='NUMERICAL_TASK_PASS' if z['numerical_mean_stop'] and z['numerical_event_stop'] else 'MEAN_GATE_UNCLOSED',full_complex_RHS_new=0,full_LU576_new=0,wall_seconds_recorded=z['wall_cumulative'],CPU_seconds_recorded=z['CPU_cumulative'],setup_included='FALSE',online_integral_included='TRUE',reference_qualification_included='FALSE',reference_status='NUMERICAL_REFERENCE',denominator_kind='FLOAT_TASK_ENVELOPE_ZL_NOT_STRICT',denominator_value_recorded=z['numerical_evidence_enclosure'][0],source_artifact='results/probability/original1d_results_v2.json',source_field=f'envelope_trajectory.cells={z["cells"]}',notes='Cumulative within the repaired run; do not add all trajectory rows. Strict fields NULL; positive upper likelihood floor1e-300 retains floating underflow uncertainty.'))
for f in sorted(R.glob('*_receipt.json')):
    z=json.loads(f.read_text());c=z['counts'];add(dict(row_id=f.stem,model='CAMPAIGN_JOB',probability_rule='ALL_WITHIN_JOB',physics_factor='MIXED_OR_REDUCED',cost_role='JOB_RECEIPT',aggregation_role='NONADDITIVE_JOB_SUBTOTAL',execution=z['status'],full_complex_RHS_new=c.get('full_complex_RHS',0),full_LU576_new=c.get('full_LU',0),Schur256_new=c.get('Schur256',0),reduced_nodes=c.get('reduced_nodes',0),reduced_complex_RHS256=c.get('reduced_complex_RHS256',0),wall_seconds_recorded=z['wall'],CPU_seconds_recorded=z['CPU'],source_artifact=str(f.relative_to(P)),source_field='counts;wall;CPU',notes='Includes within-job bookkeeping/I/O and all its reference/repair work. Imports excluded. Subtotal overlaps component rows.'))
z=json.loads((R/'aggregate_costs.json').read_text());add(dict(row_id='CAMPAIGN_TOTAL',model='ALL',probability_rule='ALL_EXECUTED_PLUS_REPLAY',physics_factor='ALL',cost_role='TOTAL',aggregation_role='NONADDITIVE_CAMPAIGN_TOTAL',full_complex_RHS_new=z['full_complex_RHS'],full_LU576_new=z['full_LU'],Schur256_new=z['Schur256'],reduced_nodes=z['reduced_nodes'],reduced_complex_RHS256=z['reduced_complex_RHS256'],wall_seconds_recorded=z['job_wall_seconds_sum'],CPU_seconds_recorded=z['CPU_seconds_sum'],setup_included='TRUE',online_integral_included='TRUE',reference_qualification_included='TRUE',source_artifact='results/probability/aggregate_costs.json',source_field='all',notes=z['timing_scope']+' Not a single end-to-end cold benchmark; historical Green/prior/checkpoint cost remains separately declared.'))
with OUT.open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=fields,extrasaction='raise');w.writeheader();w.writerows(rows)
print(json.dumps({'output':str(OUT),'rows':len(rows),'new_full_RHS':0,'new_reduced_evaluations':0,'new_benchmarks':0}))
